/**
 * Proof that this process runs inside a Cursor cloud agent, for the MCP
 * calls the Cursor backend serves under a team MCP allowlist.
 *
 * A cloud agent pod exposes a host-attested identity socket
 * (`$CURSOR_AGENT_SOCKET`, default `/run/cursor/api.sock`). `POST
 * /v1/tokens/oidc` there mints a short-lived token the platform signs for
 * the agent that owns the pod; the guest cannot name another agent. The
 * backend verifies it and serves the team's MCP allowlist for cloud agents.
 *
 * Best effort by contract: no socket, a refused mint or a slow socket all
 * yield no header, and the call goes out exactly as it would have without it.
 */
import { existsSync } from "node:fs";
import { request } from "node:http";
import { isRecord } from "../is-record.js";
export const CLOUD_AGENT_RUN_IDENTITY_HEADER = "x-cursor-cloud-agent-identity";
export const CLOUD_AGENT_RUN_IDENTITY_AUDIENCE = "https://api.cursor.com/mcp-allowlist";
export const DEFAULT_CURSOR_AGENT_SOCKET = "/run/cursor/api.sock";
const MINT_PATH = "/v1/tokens/oidc";
/** A mint is one local hop plus one backend round trip; never hold an MCP call longer. */
const MINT_TIMEOUT_MS = 3_000;
/** Remint this long before expiry so a token never expires in flight. */
export const OIDC_TOKEN_REFRESH_SKEW_MS = 60_000;
/** After a failed mint, skip minting this long so a broken socket costs nothing per call. */
const FAILURE_BACKOFF_MS = 30_000;
/** A token this close to expiry is never sent; it could expire before the backend reads it. */
const EXPIRY_MARGIN_MS = 5_000;
const MAX_RESPONSE_BYTES = 64 * 1024;
export class CloudAgentIdentity {
    constructor(options = {}) {
        this.retryAfterMs = 0;
        this.socketPath =
            options.socketPath ?? process.env.CURSOR_AGENT_SOCKET ?? DEFAULT_CURSOR_AGENT_SOCKET;
        this.mint = options.mint ?? mintAllowlistOverSocket;
        this.now = options.now ?? Date.now;
        this.socketExists = options.socketExists ?? existsSync;
    }
    /** The header to add to a Cursor MCP call, or none. Never throws. */
    async headers() {
        const token = await this.token();
        return token === undefined ? {} : { [CLOUD_AGENT_RUN_IDENTITY_HEADER]: token };
    }
    token() {
        const now = this.now();
        if (this.cached !== undefined && this.cached.expiresAtMs - OIDC_TOKEN_REFRESH_SKEW_MS > now) {
            return Promise.resolve(this.cached.token);
        }
        if (now < this.retryAfterMs || !this.socketExists(this.socketPath)) {
            return Promise.resolve(this.unexpiredToken(now));
        }
        this.inFlight ??= Promise.resolve()
            .then(() => this.mint(this.socketPath))
            .then((minted) => {
            this.cached = minted;
            return minted.token;
        })
            .catch(() => {
            // A failed refresh keeps serving the token it meant to replace until
            // that token itself expires.
            const failedAt = this.now();
            this.retryAfterMs = failedAt + FAILURE_BACKOFF_MS;
            return this.unexpiredToken(failedAt);
        })
            .finally(() => {
            this.inFlight = undefined;
        });
        return this.inFlight;
    }
    unexpiredToken(now) {
        if (this.cached === undefined || this.cached.expiresAtMs - EXPIRY_MARGIN_MS <= now) {
            this.cached = undefined;
            return undefined;
        }
        return this.cached.token;
    }
}
let shared;
/** The process-wide instance, so every MCP path shares one cached token. */
export function cloudAgentIdentity() {
    shared ??= new CloudAgentIdentity();
    return shared;
}
export function resetCloudAgentIdentityForTests() {
    shared = undefined;
}
/**
 * Wraps a fetch so each request whose URL `attachTo` accepts carries the run
 * identity header. Every other request on the same transport (an OAuth
 * discovery or token call to another host, say) passes through untouched.
 */
export function withCloudAgentIdentity(fetchImpl, attachTo, identity = cloudAgentIdentity()) {
    return async (url, init) => {
        if (!attachesTo(attachTo, url)) {
            return fetchImpl(url, init);
        }
        const extra = await identity.headers();
        if (Object.keys(extra).length === 0) {
            return fetchImpl(url, init);
        }
        const headers = new Headers(init?.headers);
        for (const [name, value] of Object.entries(extra)) {
            headers.set(name, value);
        }
        return fetchImpl(url, { ...init, headers });
    };
}
function attachesTo(attachTo, url) {
    try {
        return attachTo(url instanceof URL ? url : new URL(url));
    }
    catch {
        return false;
    }
}
/**
 * Mint one audience on the pod identity socket.
 * The MCP allowlist path calls this with its fixed audience.
 */
export function mintOidcOverSocket(input) {
    const body = JSON.stringify({ aud: input.audience });
    return new Promise((resolve) => {
        let settled = false;
        const finish = (result) => {
            if (settled) {
                return;
            }
            settled = true;
            resolve(result);
        };
        const req = request({
            socketPath: input.socketPath,
            path: MINT_PATH,
            method: "POST",
            headers: {
                "content-type": "application/json",
                "content-length": Buffer.byteLength(body),
            },
            timeout: input.timeoutMs,
        }, (res) => {
            const chunks = [];
            let size = 0;
            res.on("data", (chunk) => {
                size += chunk.length;
                if (size > MAX_RESPONSE_BYTES) {
                    finish({ kind: "malformed" });
                    req.destroy();
                    return;
                }
                chunks.push(chunk);
            });
            res.on("end", () => {
                const text = Buffer.concat(chunks).toString("utf8");
                const status = res.statusCode ?? 0;
                if (status !== 200) {
                    finish({ kind: "http", status, reason: reasonFromBody(text) });
                    return;
                }
                try {
                    const parsed = parseMintResponse(text);
                    finish({ kind: "token", token: parsed.token, expiresAtMs: parsed.expiresAtMs });
                }
                catch {
                    finish({ kind: "malformed" });
                }
            });
            res.on("error", (error) => {
                finish({ kind: "transport", code: nodeErrorCode(error) });
            });
        });
        req.on("timeout", () => {
            finish({ kind: "timeout" });
            req.destroy();
        });
        req.on("error", (error) => {
            finish({ kind: "transport", code: nodeErrorCode(error) });
        });
        req.end(body);
    });
}
/** The allowlist audience, on the short timeout the MCP path already uses. */
function mintAllowlistOverSocket(socketPath) {
    return mintOidcOverSocket({
        socketPath,
        audience: CLOUD_AGENT_RUN_IDENTITY_AUDIENCE,
        timeoutMs: MINT_TIMEOUT_MS,
    }).then((result) => {
        if (result.kind === "token") {
            return { token: result.token, expiresAtMs: result.expiresAtMs };
        }
        throw new Error("identity mint failed");
    });
}
function reasonFromBody(text) {
    try {
        const parsed = JSON.parse(text);
        if (!isRecord(parsed) || typeof parsed.error !== "string" || parsed.error === "") {
            return undefined;
        }
        return parsed.error;
    }
    catch {
        return undefined;
    }
}
function nodeErrorCode(error) {
    if (!isRecord(error) || typeof error.code !== "string" || error.code === "") {
        return undefined;
    }
    return error.code;
}
export function parseMintResponse(text) {
    const parsed = JSON.parse(text);
    if (!isRecord(parsed)) {
        throw new Error("identity mint response is not an object");
    }
    if (typeof parsed.token !== "string" || parsed.token === "") {
        throw new Error("identity mint response has no token");
    }
    if (typeof parsed.expires_at !== "number" || !Number.isFinite(parsed.expires_at)) {
        throw new Error("identity mint response has no expiry");
    }
    return { token: parsed.token, expiresAtMs: parsed.expires_at * 1000 };
}
